#include <iBleHID.h>

constexpr uint8_t BUTTON_PIN = 4;
BleKeyboard keyboard;
bool wasPressed = false;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  keyboard.begin();
}

void loop() {
  const bool pressed = digitalRead(BUTTON_PIN) == LOW;
  if (pressed && !wasPressed && keyboard.isConnected()) {
    keyboard.write('a');
  }
  wasPressed = pressed;
  delay(25);
}
